import React from 'react';

const Navbar = () => {
  return (
    <nav className="glass-effect border-b border-white/20 px-6 py-4">
      <div className="flex items-center justify-between">
        {/* Left side - Logo */}
        <div className="flex items-center space-x-2">
          <div className="heart-icon"></div>
          <span className="text-white text-xl font-bold">Lovable</span>
        </div>

        {/* Center - Navigation Links */}
        <div className="hidden md:flex items-center space-x-8">
          <a href="#" className="text-white/80 hover:text-white transition-colors">Community</a>
          <a href="#" className="text-white/80 hover:text-white transition-colors">Pricing</a>
          <a href="#" className="text-white/80 hover:text-white transition-colors">Enterprise</a>
        </div>

        {/* Right side - Action Buttons */}
        <div className="flex items-center space-x-4">
          <button className="px-4 py-2 text-white/80 hover:text-white transition-colors">
            Log in
          </button>
          <button className="px-6 py-2 bg-white text-gray-900 rounded-lg hover:bg-white/90 transition-colors font-medium">
            Get started
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
